void GameScene::Update(float deltatime)
{
	// Creation de topus les objets de la scene qui ne pouvaient pas etre crees dans la fonciton Start
	auto pos = m_playerTest.GetPosition();
	if (pos.z < -60)
	{
		float reduction = (std::abs((-30 - pos.x)) / 150) * 100;
		float riverSound = 100 - reduction;
		riverSound = Utils::clamp(riverSound, 0, 80)/50;
		if (m_soundTest) m_soundTest->SetVolume(riverSound);
	}
	else
	{
		float reduction = (std::abs((61 - pos.x)) / 250) * 100;
		float riverSound = 100 - reduction;
		riverSound = Utils::clamp(riverSound, 0, 70)/35;
		if (m_soundTest) m_soundTest->SetVolume(riverSound);
	}

	if (weedsCreated)
	{
		AdditionnalSceneObjects::CreateObjects(this);
		AdditionnalSceneObjects::CreateGrass(this);
		//CreateGrass();
		init2 = true;
		weedsCreated = false;
	}
	if (!init2)
	{
		//CreateWeeds();
		AdditionnalSceneObjects::CreateWeeds(this);
		CreateAdditionalHitboxes();

		weedsCreated = true;
	}
	m_playerTest.SetTransformRotation({ 0,90,0 });
	m_cam.SetTransformRotation({ 0,90,0 });

	//debug fps
	// inside main loop, each frame
	{
		// debug fps (use deltatime provided by engine)
		double dtMs = double(deltatime) * 1000.0;
		++s_frameCount;
		s_accumMs += dtMs;

		// every 5 seconds print avg FPS and avg frame ms
		if (s_accumMs >= 5000.0)
		{
			double avgMs = s_accumMs / double(s_frameCount);
			double fps = 1000.0 / avgMs;
			std::ostringstream ss;
			ss << "Perf: avgMs=" << avgMs << " ms, avgFPS=" << fps << " DrawCalls=" << g_drawCalls << "\n";
			OutputDebugStringA(ss.str().c_str()); // visible in VS Output
			std::cout << ss.str();
			s_frameCount = 0;
			s_accumMs = 0.0;
			g_drawCalls = 0;
		}

		// every 30 seconds log memory usage (working set)
		// NOTE: renamed 'now' to 'now_tp' to avoid redefinition errors
		auto now_tp = std::chrono::high_resolution_clock::now();
		auto sinceReport = std::chrono::duration<double>(now_tp - s_lastReport).count();
		if (sinceReport >= 30.0)
		{
			PROCESS_MEMORY_COUNTERS pmc{};
			if (GetProcessMemoryInfo(GetCurrentProcess(), &pmc, sizeof(pmc)))
			{
				std::ostringstream m;
				m << "ProcessMem: WorkingSet=" << pmc.WorkingSetSize
					<< " bytes, PagefileUsage=" << pmc.PagefileUsage << "\n";
				OutputDebugStringA(m.str().c_str());
				std::cout << m.str();
			}
			s_lastReport = now_tp;
		}
	}


	//Pause menu
	if (InputManager::GetKeyIsReleased(VK_ESCAPE))
	{
		m_pauseIsOpen = !m_pauseIsOpen;
		if (m_pauseIsOpen)
		{
			SpawnMenu();
		}
		else
		{
			RemoveMenu();
		}
	}
	if (m_pauseIsOpen)
	{
		if (mp_btnMainMenu->GetMouseOnBtn())
		{
			mp_btnMainMenu->SetScale({ 170, 100, 0 });
		}
		if (!mp_btnMainMenu->GetMouseOnBtn())
		{
			mp_btnMainMenu->SetScale({ 120, 50, 0 });
		}
		if (mp_btnMainMenu->GetBtnIsClicked())
		{
			ChangeScene("MainMenuScene");
			return;
		}
	}
	else
	{
		if (m_playerTest.IsAlive() || m_pauseIsOpen)
		{
			m_fpsCam.Update(deltatime);
		}

		if (InputManager::GetKeyIsReleased('N'))
		{
			StopMusicPlex();
		}
		if (InputManager::GetKeyIsReleased('K'))
		{
			SetEnnemyNbDebugOnly(0);
		}

		//for (auto& gameObject : m_sceneGameObjects)
		//{
		//	gameObject.get()->OnUpdate(deltatime);
		//}

		std::vector<GameObject*> snapshot;
		snapshot.reserve(m_sceneGameObjects.size());
		for (auto& up : m_sceneGameObjects)
		{
			if (up) snapshot.push_back(up.get());
		}
		for (auto* go : snapshot)
		{
			if (go) go->OnUpdate(deltatime);
		}

		//// PlayerState
		m_playerTest.OnUpdate(deltatime);

		//Portal System
		//PortalSystem();

		if (InputManager::GetKeyIsPressed('R'))
		{
			//FindGameObjectByName("player")->SetPosition({ 45, 3, -60 });
		}

		if (InputManager::GetKeyIsReleased('T'))
		{
			OutputDebugStringA(("\nPlayer State : " + std::string(m_playerTest.GetCurrentStateName())).c_str());
		}

		if (InputManager::GetKeyIsReleased(VK_ESCAPE))
		{
			m_pauseIsOpen = !m_pauseIsOpen;

			if (m_pauseIsOpen)
			{
				SpawnMenu();
				m_fpsCam.SetAlwaysActive(false);
			}
			else
			{
				RemoveMenu();
				m_fpsCam.SetAlwaysActive(true);
			}

		}

		// Change scene [ALLWAYS AT THE END SO THERE IS NO OTHER CODE RUNNING AFTER IN THIS SCENE]
		if (InputManager::GetKeyIsReleased('A'))
		{
			ChangeScene("DevScene");
			return;
		}

		if (m_youWin)
		{
			m_chronoChangeScene -= 1.f * deltatime;

			if (m_chronoChangeScene <= 0)
			{
				ChangeScene("MainMenuScene");
				return;
			}
		}
	}
}

void GameScene::Release()
{
}

void GameScene::SpawnMenu()
{
	RECT renderZone;
	GetClientRect(mp_sceneManager->GetGameManager()->GetRenderingManager().GetGraphicsDevice()->GetWindow(), &renderZone);
	UINT renderWidth = renderZone.right - renderZone.left;
	UINT renderHeight = renderZone.bottom - renderZone.top;

	// Pause menu
	CreateGameObject("pauseMenu", TYPE_2D, true);
	FindGameObjectByName("pauseMenu")->SetMesh(MESHES::LOCAL_SQUARE);
	FindGameObjectByName("pauseMenu")->SetTexture(TEXTURES::PAUSEMENU);
	FindGameObjectByName("pauseMenu")->SetPosition({ (float)renderWidth / 2, (float)renderHeight / 2, 0 });
	FindGameObjectByName("pauseMenu")->SetScale({ (float)renderWidth * 0.2f, (float)renderHeight * 0.4f, 0 });
	FindGameObjectByName("pauseMenu")->GetComponent<TransformComponent>()->AddRotation(0, 0, 180);

	// Buttons
	mp_btnMainMenu = &CreateGameObject<Button>(this, mp_sceneManager->GetWindow(), TEXTURES::BTN_MAINMENU, "btnMainMenu");
	mp_btnMainMenu->SetScale({ 120, 50, 0 });
	auto posPauseMenu = FindGameObjectByName("pauseMenu")->GetPosition();
	mp_btnMainMenu->SetPosition({ posPauseMenu.x,posPauseMenu.y + 140,posPauseMenu.z });
	m_fpsCam.SetAlwaysActive(false);
}

void GameScene::RemoveMenu()
{
	DestroyGameObject(*FindGameObjectByName("pauseMenu"));
	DestroyGameObject(*FindGameObjectByName("btnMainMenu"));
	m_fpsCam.SetAlwaysActive(true);
}

